EXPECTED={'team/index.html': '0b84711dd8164406279c6147ee5a0c2ee557c9a5f9841c29e09719b03db5a395', 'team-2/index.html': 'aa8dc1a7421c72ab2e6792f4fa40170825c466fa520a84407dd53c71cb4c1e37', 'team/golishenkov-vladislav/index.html': '7e005f1c6c76f0a53f267b9ca4b8895226869f6b83a2671456bfb2f5a3ef5a64'}
ASSET='49e41ba08427739db0b623256a9e439d9a44040522d4e130993610680cf04b4f'
DATA=''
from pathlib import Path
import base64,hashlib,datetime,shutil,os,re
root=Path('/var/www/azmednsk-preview')
new='/assets/golishenkov-approved-20261115.webp'
old=['/assets/92e10e4dd7964b066f2d.png','/assets/az-loading-20261021/image-4a026f1daf14-w320-c97456625fa266d8.webp','/assets/az-loading-20261021/image-4a026f1daf14-w512-8e8c04976c939cc3.webp']
sha=lambda b:hashlib.sha256(b).hexdigest()
blob=base64.b64decode(DATA)
assert sha(blob)==ASSET
changes={}
for p in root.rglob('*'):
 if p.is_symlink() or not p.is_file() or p.suffix.lower() not in {'.html','.css','.js','.json','.xml'}:continue
 before=p.read_bytes()
 try:s=before.decode('utf-8')
 except UnicodeDecodeError:continue
 if not any(x in s for x in old):continue
 def image(m):
  t=m.group(0)
  if not any(x in t for x in old):return t
  t=re.sub(r'\s+(?:srcset|sizes)=["\'][^"\']*["\']','',t)
  return t
 s=re.sub(r'<img\b[^>]*>',image,s,flags=re.I)
 for x in old:s=s.replace(x,new)
 changes[p]=(before,s.encode())
for rel,h in EXPECTED.items():
 p=root/rel
 assert p in changes and sha(changes[p][0])==h,'STOP: page changed '+rel
assert changes,'STOP: no old references'
a=root/new.lstrip('/')
assert not a.exists() or a.read_bytes()==blob,'STOP: asset conflict'
backup=Path('/var/backups/azmednsk')/('golishenkov-photo-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
backup.mkdir(parents=True)
for p,(before,after) in changes.items():
 dst=backup/p.relative_to(root);dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dst)
for x in old:
 src=root/x.lstrip('/')
 if src.exists():
  dst=backup/x.lstrip('/');dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dst)
for p,(before,after) in changes.items():assert p.read_bytes()==before,'STOP: concurrent change'
a.write_bytes(blob);a.chmod(0o644)
try:
 for p,(before,after) in changes.items():
  tmp=p.with_name(p.name+'.photo-tmp');tmp.write_bytes(after);shutil.copystat(p,tmp);os.replace(tmp,p)
 for p,(_,after) in changes.items():assert p.read_bytes()==after
 assert sha(a.read_bytes())==ASSET
except Exception:
 for p in changes:shutil.copy2(backup/p.relative_to(root),p)
 raise
print('GOLISHENKOV_PHOTO=PASS; OLD_REFERENCES=REPLACED; RANDOM_OLD_PHOTO=NONE')
print('PAGES='+str(len(changes))+'; WEBP_BYTES='+str(len(blob)))
print('BACKUP='+str(backup))
print('URL=https://azmednsk.ru/team/golishenkov-vladislav/')
